-- Paso 1: Categorias
SELECT v.nombre FROM (VALUES
    ('AMPOLLAS'),
    ('BEBIDAS GASIFICADAS Y GOLOSINAS'),
    ('CREMAS, UNGUENTOS, GEL Y GOTAS'),
    ('DISPOSITIVOS MEDICOS Y GALENICOS'),
    ('MEDICAMENTOS DE MARCA Y JARABES DE MARCA'),
    ('MEDICAMENTOS GENERICOS Y JARABES GENERICOS'),
    ('METODOS ANTICONCEPTIVOS Y CUIDADO MUJER'),
    ('PAPEPELERIA'),
    ('PERFUMERIA Y CUIDADO PERSONAL'),
    ('PRESERVATIVOS, SILDENAFILO Y LUBRICANTE INTIMO'),
    ('SECCION BEBE'),
    ('VITAMINAS Y LECHES')
) AS v(nombre)
WHERE NOT EXISTS (SELECT 1 FROM categorias WHERE UPPER(categorias.nombre) = UPPER(v.nombre));

